___CSS_LOADER_EXPORT___.push([module.id, `/* Reserve land by crop. Value, name and share ride on one line-up above the
   columns (like VH); behind each lit gradient bar stands a faded full-height
   column of the same colour (like VH). Click = filter the reserve layer on the map. */
.agri-reserve-crop-card {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 0;
  padding: 12px 16px 10px;
  border-radius: var(--agri-widget-radius);
  /* Sizes below follow this card (cqi / @container), not the viewport: the
     Graff slot is 2fr of the bottom row on desktop and full width on phones. */
  container: agri-reserve-crop/size;
  background: var(--agri-widget-panel-bg, #1f2030);
  color: #e9f8ff;
  --reserve-surface: var(--agri-widget-panel-bg, #1f2030);
  --reserve-text: #e9f8ff;
  --reserve-text-2: rgba(233, 248, 255, 0.72);
  --reserve-text-3: rgba(233, 248, 255, 0.52);
  --reserve-ring-track: rgba(233, 248, 255, 0.14);
  /* Faded column behind each bar, as VH tints it on dark. */
  --reserve-track-mix: 26%;
  --reserve-track-mix-hover: 34%;
  --reserve-divider: rgba(233, 248, 255, 0.12);
  --reserve-focus: rgba(233, 248, 255, 0.55);
}

.agri-reserve-crop-card.light-theme {
  background: #ffffff;
  color: #0f172a;
  --reserve-surface: #ffffff;
  --reserve-text: #0f172a;
  --reserve-text-2: rgba(15, 23, 42, 0.72);
  --reserve-text-3: rgba(15, 23, 42, 0.52);
  --reserve-ring-track: rgba(15, 23, 42, 0.1);
  --reserve-track-mix: 10%;
  --reserve-track-mix-hover: 15%;
  --reserve-divider: rgba(15, 23, 42, 0.12);
  --reserve-focus: rgba(15, 23, 42, 0.45);
}

.agri-reserve-crop-title {
  flex: 0 0 auto;
  margin-bottom: 10px;
  /* Same title look as VH / Region / Ekin / Index (agri-dashboard.css). */
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agri-reserve-crop-body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
}

/* ---- plot ---- */
.agri-reserve-crop-grid {
  position: relative;
  display: grid;
  height: 100%;
  /* Like VH: no gap; each column pads 4px, so bars sit ~8px apart. */
  column-gap: 0;
  align-items: stretch;
  /* Column width bounds scale with the card. Few crops: columns stop at the
     max and the group is centred (safe: an overflowing row still starts at 0). */
  --reserve-col-min: clamp(64px, 11cqi, 96px);
  --reserve-col-max: clamp(110px, 24cqi, 200px);
  justify-content: safe center;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scroll-snap-type: x proximity;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: var(--reserve-ring-track) transparent;
  transition: opacity 200ms ease;
}

/* Faded edge where more columns hide off-card (set from scroll position). */
.agri-reserve-crop-grid.has-more-end {
  -webkit-mask-image: linear-gradient(to right, #000 calc(100% - 32px), transparent);
  mask-image: linear-gradient(to right, #000 calc(100% - 32px), transparent);
}

.agri-reserve-crop-grid.has-more-start {
  -webkit-mask-image: linear-gradient(to right, transparent, #000 32px);
  mask-image: linear-gradient(to right, transparent, #000 32px);
}

.agri-reserve-crop-grid.has-more-start.has-more-end {
  -webkit-mask-image: linear-gradient(to right, transparent, #000 32px, #000 calc(100% - 32px), transparent);
  mask-image: linear-gradient(to right, transparent, #000 32px, #000 calc(100% - 32px), transparent);
}

.agri-reserve-crop-grid.is-refreshing {
  opacity: 0.45;
  pointer-events: none;
}

/* Column = button: header on top, track below. */
.agri-reserve-crop-col {
  all: unset;
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  padding: 2px 4px 0;
  border-radius: 12px;
  cursor: pointer;
  scroll-snap-align: start;
  transition: opacity 180ms ease, background-color 180ms ease;
}

/* Hairline divider between columns, inset top and bottom (like VH). */
.agri-reserve-crop-col:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 14px;
  bottom: 14px;
  right: 0;
  width: 1px;
  background: var(--reserve-divider);
  pointer-events: none;
}

.agri-reserve-crop-col:disabled {
  cursor: default;
}

.agri-reserve-crop-col:focus-visible {
  outline: 2px solid var(--reserve-focus);
  outline-offset: 2px;
}

/* Selected: a soft wash of its colour, no outline (like VH). */
.agri-reserve-crop-col.is-selected {
  background: color-mix(in srgb, var(--bar-color) 10%, transparent);
}

.agri-reserve-crop-col:not(:disabled):not(.is-selected):hover {
  background: color-mix(in srgb, var(--bar-color) 6%, transparent);
}

.agri-reserve-crop-col.is-dimmed {
  opacity: 0.42;
}

.agri-reserve-crop-col.is-dimmed:hover {
  opacity: 0.75;
}

/* ---- header: value / name / share, aligned across columns ---- */
.agri-reserve-crop-head {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 4px 2px 0;
  text-align: center;
}

.agri-reserve-crop-value {
  font-size: clamp(12px, 1.4cqi + 6px, 16px);
  line-height: 1.15;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--reserve-text);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  animation: agri-reserve-value-in 300ms ease calc(var(--bar-delay) + 260ms) both;
}

.agri-reserve-crop-value small {
  font-size: 0.74em;
  font-weight: 500;
  color: var(--reserve-text-2);
}

.agri-reserve-crop-label {
  max-width: 100%;
  font-size: clamp(11px, 0.9cqi + 6px, 13.5px);
  font-weight: 500;
  line-height: 1.2;
  color: var(--reserve-text-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agri-reserve-crop-col.is-selected .agri-reserve-crop-label {
  color: var(--reserve-text);
  font-weight: 600;
}

.agri-reserve-crop-share {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: clamp(10px, 0.6cqi + 6px, 11.5px);
  font-weight: 500;
  color: var(--reserve-text-3);
  font-variant-numeric: tabular-nums;
}

.agri-reserve-crop-ring {
  width: 12px;
  height: 12px;
  transform: rotate(-90deg);
}

.agri-reserve-crop-ring circle {
  fill: none;
  stroke-width: 3;
}

.agri-reserve-crop-ring-track {
  stroke: var(--reserve-ring-track);
}

.agri-reserve-crop-ring-arc {
  stroke: var(--bar-color);
  stroke-linecap: round;
}

@keyframes agri-reserve-value-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
/* ---- track + bar ---- */
.agri-reserve-crop-plot {
  display: flex;
  flex: 1 1 auto;
  justify-content: center;
  min-height: 40px;
  padding: 8px 0 6px;
  box-sizing: border-box;
}

/* Full-height faded column of the crop colour behind the bar (like VH):
   shows the headroom to the largest crop. */
.agri-reserve-crop-track {
  position: relative;
  width: 100%;
  /* Wide columns (few crops) keep a bar shape instead of a slab. */
  max-width: 120px;
  height: 100%;
  overflow: hidden;
  border-radius: 14px;
  background: color-mix(in srgb, var(--bar-color) var(--reserve-track-mix), transparent);
  transition: background-color 180ms ease;
}

/* Bright bar in the full crop colour (like VH): flat body, a light sheen on
   the cap, a glow of its own colour. No darkening toward the base. */
.agri-reserve-crop-bar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: max(var(--bar-fill), 10px);
  border-radius: 14px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--bar-color) 80%, #ffffff) 0%, var(--bar-color) 20%, var(--bar-color) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45), 0 8px 22px -8px color-mix(in srgb, var(--bar-color) 85%, transparent);
  transform-origin: bottom center;
  animation: agri-reserve-bar-grow 650ms cubic-bezier(0.22, 1, 0.36, 1) var(--bar-delay) both;
  transition: filter 160ms ease;
}

/* Glass highlight on the cap. */
.agri-reserve-crop-bar::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 24%;
  right: 24%;
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.5);
}

.agri-reserve-crop-col:not(:disabled):hover .agri-reserve-crop-bar {
  filter: brightness(1.08);
}

.agri-reserve-crop-col:not(:disabled):hover .agri-reserve-crop-track {
  --reserve-track-mix: var(--reserve-track-mix-hover);
}

/* Selected bar lights up with a wider glow of its own colour. */
.agri-reserve-crop-col.is-selected .agri-reserve-crop-bar {
  filter: brightness(1.12) saturate(1.08);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), 0 0 22px -2px color-mix(in srgb, var(--bar-color) 70%, transparent);
}

.agri-reserve-crop-col.is-selected .agri-reserve-crop-track {
  overflow: visible;
}

@keyframes agri-reserve-bar-grow {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}
/* Screen-reader table twin. */
.agri-reserve-crop-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .agri-reserve-crop-bar,
  .agri-reserve-crop-value {
    animation: none;
  }
  .agri-reserve-crop-col {
    transition: none;
  }
}
/* ---- card size steps ---- */
/* Narrow card (phone / small tablet column). */
@container agri-reserve-crop (max-width: 460px) {
  .agri-reserve-crop-title {
    margin-bottom: 6px;
  }
  .agri-reserve-crop-col {
    padding: 2px 2px 0;
  }
  .agri-reserve-crop-track,
  .agri-reserve-crop-bar {
    border-radius: 10px;
  }
}
/* Short card: drop the share ring row, tighten the header and the plot. */
@container agri-reserve-crop (max-height: 230px) {
  .agri-reserve-crop-title {
    margin-bottom: 4px;
  }
  .agri-reserve-crop-head {
    gap: 0;
    padding-top: 2px;
  }
  .agri-reserve-crop-share {
    display: none;
  }
  .agri-reserve-crop-plot {
    min-height: 28px;
    padding: 4px 0 4px;
  }
}
/* Very short card: the bars matter most; the list keeps its aria-label. */
@container agri-reserve-crop (max-height: 170px) {
  .agri-reserve-crop-title {
    display: none;
  }
  .agri-reserve-crop-col:not(:last-child)::after {
    top: 6px;
    bottom: 6px;
  }
}
/* The card padding cannot use its own cqi; step it with the slot instead. */
@media (max-width: 860px) {
  .agri-reserve-crop-card {
    padding: 10px 10px 8px;
  }
}
/* ---- states ---- */
.agri-reserve-crop-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 100%;
  text-align: center;
  font-size: 13px;
}

.agri-reserve-crop-empty h3,
.agri-reserve-crop-empty p {
  margin: 0;
  font-size: inherit;
}

/* Light mode: unit, crop name and share in solid black; names a bit bolder. */
.agri-reserve-crop-card.light-theme .agri-reserve-crop-value small,
.agri-reserve-crop-card.light-theme .agri-reserve-crop-share {
  color: #000000;
}

.agri-reserve-crop-card.light-theme .agri-reserve-crop-label {
  color: #000000;
  font-weight: 600;
}

.agri-reserve-crop-card.light-theme .agri-reserve-crop-col.is-selected .agri-reserve-crop-label {
  font-weight: 700;
}`, "",{"version":3,"sources":["webpack://./your-extensions/widgets/Agri3/Agro_widgetV5/src/panels/ReserveCropPanel/runtime/ReserveCrop.css"],"names":[],"mappings":"AAAA;;sFAAA;AAIA;EACE,aAAA;EACA,sBAAA;EACA,sBAAA;EACA,WAAA;EACA,YAAA;EACA,aAAA;EACA,uBAAA;EACA,wCAAA;EACA;+EAAA;EAEA,iCAAA;EACA,gDAAA;EACA,cAAA;EACA,uDAAA;EACA,uBAAA;EACA,2CAAA;EACA,2CAAA;EACA,+CAAA;EACA,0DAAA;EACA,wBAAA;EACA,8BAAA;EACA,4CAAA;EACA,0CAAA;AAAF;;AAGA;EACE,mBAAA;EACA,cAAA;EACA,0BAAA;EACA,uBAAA;EACA,wCAAA;EACA,wCAAA;EACA,2CAAA;EACA,wBAAA;EACA,8BAAA;EACA,yCAAA;EACA,uCAAA;AAAF;;AAGA;EACE,cAAA;EACA,mBAAA;EACA,wEAAA;EACA,eAAA;EACA,gBAAA;EACA,sBAAA;EACA,yBAAA;EACA,iBAAA;EACA,mBAAA;EACA,gBAAA;EACA,uBAAA;AAAF;;AAGA;EACE,kBAAA;EACA,cAAA;EACA,aAAA;AAAF;;AAGA,mBAAA;AAEA;EACE,kBAAA;EACA,aAAA;EACA,YAAA;EACA,mEAAA;EACA,aAAA;EACA,oBAAA;EACA;iFAAA;EAEA,2CAAA;EACA,6CAAA;EACA,4BAAA;EACA,gBAAA;EACA,kBAAA;EACA,8BAAA;EACA,6BAAA;EACA,iCAAA;EACA,qBAAA;EACA,sDAAA;EACA,8BAAA;AADF;;AAIA,4EAAA;AACA;EACE,kFAAA;EACA,0EAAA;AADF;;AAIA;EACE,qEAAA;EACA,6DAAA;AADF;;AAIA;EACE,0GAAA;EACA,kGAAA;AADF;;AAIA;EACE,aAAA;EACA,oBAAA;AADF;;AAIA,iDAAA;AACA;EACE,UAAA;EACA,kBAAA;EACA,aAAA;EACA,sBAAA;EACA,YAAA;EACA,aAAA;EACA,sBAAA;EACA,kBAAA;EACA,mBAAA;EACA,eAAA;EACA,wBAAA;EACA,2DAAA;AADF;;AAIA,sEAAA;AACA;EACE,WAAA;EACA,kBAAA;EACA,SAAA;EACA,YAAA;EACA,QAAA;EACA,UAAA;EACA,kCAAA;EACA,oBAAA;AADF;;AAIA;EACE,eAAA;AADF;;AAIA;EACE,uCAAA;EACA,mBAAA;AADF;;AAIA,+DAAA;AACA;EACE,iEAAA;AADF;;AAIA;EACE,gEAAA;AADF;;AAIA;EACE,aAAA;AADF;;AAIA;EACE,aAAA;AADF;;AAIA,mEAAA;AAEA;EACE,aAAA;EACA,cAAA;EACA,sBAAA;EACA,mBAAA;EACA,QAAA;EACA,YAAA;EACA,kBAAA;EACA,kBAAA;AAFF;;AAKA;EACE,0CAAA;EACA,iBAAA;EACA,gBAAA;EACA,uBAAA;EACA,0BAAA;EACA,kCAAA;EACA,mBAAA;EACA,+EAAA;AAFF;;AAKA;EACE,iBAAA;EACA,gBAAA;EACA,4BAAA;AAFF;;AAKA;EACE,eAAA;EACA,4CAAA;EACA,gBAAA;EACA,gBAAA;EACA,4BAAA;EACA,mBAAA;EACA,gBAAA;EACA,uBAAA;AAFF;;AAKA;EACE,0BAAA;EACA,gBAAA;AAFF;;AAKA;EACE,oBAAA;EACA,mBAAA;EACA,QAAA;EACA,4CAAA;EACA,gBAAA;EACA,4BAAA;EACA,kCAAA;AAFF;;AAKA;EACE,WAAA;EACA,YAAA;EACA,yBAAA;AAFF;;AAKA;EACE,UAAA;EACA,eAAA;AAFF;;AAKA;EACE,iCAAA;AAFF;;AAKA;EACE,wBAAA;EACA,qBAAA;AAFF;;AAKA;EACE;IACE,UAAA;EAFF;EAIA;IACE,UAAA;EAFF;AACF;AAKA,0BAAA;AAEA;EACE,aAAA;EACA,cAAA;EACA,uBAAA;EACA,gBAAA;EACA,kBAAA;EACA,sBAAA;AAJF;;AAOA;4CAAA;AAEA;EACE,kBAAA;EACA,WAAA;EACA,iEAAA;EACA,gBAAA;EACA,YAAA;EACA,gBAAA;EACA,mBAAA;EACA,sFAAA;EACA,uCAAA;AAJF;;AAOA;qEAAA;AAEA;EACE,kBAAA;EACA,OAAA;EACA,QAAA;EACA,SAAA;EACA,kCAAA;EACA,mBAAA;EACA,sIAAA;EAMA,0HACE;EAEF,+BAAA;EACA,2FAAA;EACA,6BAAA;AAXF;;AAcA,gCAAA;AACA;EACE,WAAA;EACA,kBAAA;EACA,QAAA;EACA,SAAA;EACA,UAAA;EACA,WAAA;EACA,kBAAA;EACA,oCAAA;AAXF;;AAcA;EACE,wBAAA;AAXF;;AAcA;EACE,mDAAA;AAXF;;AAcA,gEAAA;AACA;EACE,uCAAA;EACA,uHACE;AAZJ;;AAgBA;EACE,iBAAA;AAbF;;AAgBA;EACE;IACE,oBAAA;EAbF;EAeA;IACE,oBAAA;EAbF;AACF;AAgBA,8BAAA;AACA;EACE,kBAAA;EACA,UAAA;EACA,WAAA;EACA,gBAAA;EACA,mBAAA;EACA,qBAAA;EACA,mBAAA;AAdF;;AAiBA;EACE;;IAEE,eAAA;EAdF;EAgBA;IACE,gBAAA;EAdF;AACF;AAiBA,8BAAA;AAEA,+CAAA;AACA;EACE;IACE,kBAAA;EAhBF;EAkBA;IACE,kBAAA;EAhBF;EAkBA;;IAEE,mBAAA;EAhBF;AACF;AAmBA,0EAAA;AACA;EACE;IACE,kBAAA;EAjBF;EAmBA;IACE,MAAA;IACA,gBAAA;EAjBF;EAmBA;IACE,aAAA;EAjBF;EAmBA;IACE,gBAAA;IACA,kBAAA;EAjBF;AACF;AAoBA,0EAAA;AACA;EACE;IACE,aAAA;EAlBF;EAoBA;IACE,QAAA;IACA,WAAA;EAlBF;AACF;AAqBA,4EAAA;AACA;EACE;IACE,sBAAA;EAnBF;AACF;AAsBA,qBAAA;AAEA;EACE,aAAA;EACA,sBAAA;EACA,mBAAA;EACA,uBAAA;EACA,QAAA;EACA,YAAA;EACA,kBAAA;EACA,eAAA;AArBF;;AAwBA;;EAEE,SAAA;EACA,kBAAA;AArBF;;AAwBA,8EAAA;AACA;;EAEE,cAAA;AArBF;;AAwBA;EACE,cAAA;EACA,gBAAA;AArBF;;AAwBA;EACE,gBAAA;AArBF","sourcesContent":["/* Reserve land by crop. Value, name and share ride on one line-up above the\n   columns (like VH); behind each lit gradient bar stands a faded full-height\n   column of the same colour (like VH). Click = filter the reserve layer on the map. */\n\n.agri-reserve-crop-card {\n  display: flex;\n  flex-direction: column;\n  box-sizing: border-box;\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n  padding: 12px 16px 10px;\n  border-radius: var(--agri-widget-radius);\n  /* Sizes below follow this card (cqi / @container), not the viewport: the\n     Graff slot is 2fr of the bottom row on desktop and full width on phones. */\n  container: agri-reserve-crop / size;\n  background: var(--agri-widget-panel-bg, #1f2030);\n  color: #e9f8ff;\n  --reserve-surface: var(--agri-widget-panel-bg, #1f2030);\n  --reserve-text: #e9f8ff;\n  --reserve-text-2: rgba(233, 248, 255, 0.72);\n  --reserve-text-3: rgba(233, 248, 255, 0.52);\n  --reserve-ring-track: rgba(233, 248, 255, 0.14);\n  /* Faded column behind each bar, as VH tints it on dark. */\n  --reserve-track-mix: 26%;\n  --reserve-track-mix-hover: 34%;\n  --reserve-divider: rgba(233, 248, 255, 0.12);\n  --reserve-focus: rgba(233, 248, 255, 0.55);\n}\n\n.agri-reserve-crop-card.light-theme {\n  background: #ffffff;\n  color: #0f172a;\n  --reserve-surface: #ffffff;\n  --reserve-text: #0f172a;\n  --reserve-text-2: rgba(15, 23, 42, 0.72);\n  --reserve-text-3: rgba(15, 23, 42, 0.52);\n  --reserve-ring-track: rgba(15, 23, 42, 0.1);\n  --reserve-track-mix: 10%;\n  --reserve-track-mix-hover: 15%;\n  --reserve-divider: rgba(15, 23, 42, 0.12);\n  --reserve-focus: rgba(15, 23, 42, 0.45);\n}\n\n.agri-reserve-crop-title {\n  flex: 0 0 auto;\n  margin-bottom: 10px;\n  /* Same title look as VH / Region / Ekin / Index (agri-dashboard.css). */\n  font-size: 14px;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  line-height: 1.25;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.agri-reserve-crop-body {\n  position: relative;\n  flex: 1 1 auto;\n  min-height: 0;\n}\n\n/* ---- plot ---- */\n\n.agri-reserve-crop-grid {\n  position: relative;\n  display: grid;\n  height: 100%;\n  /* Like VH: no gap; each column pads 4px, so bars sit ~8px apart. */\n  column-gap: 0;\n  align-items: stretch;\n  /* Column width bounds scale with the card. Few crops: columns stop at the\n     max and the group is centred (safe: an overflowing row still starts at 0). */\n  --reserve-col-min: clamp(64px, 11cqi, 96px);\n  --reserve-col-max: clamp(110px, 24cqi, 200px);\n  justify-content: safe center;\n  overflow-x: auto;\n  overflow-y: hidden;\n  overscroll-behavior-x: contain;\n  scroll-snap-type: x proximity;\n  -webkit-overflow-scrolling: touch;\n  scrollbar-width: thin;\n  scrollbar-color: var(--reserve-ring-track) transparent;\n  transition: opacity 200ms ease;\n}\n\n/* Faded edge where more columns hide off-card (set from scroll position). */\n.agri-reserve-crop-grid.has-more-end {\n  -webkit-mask-image: linear-gradient(to right, #000 calc(100% - 32px), transparent);\n  mask-image: linear-gradient(to right, #000 calc(100% - 32px), transparent);\n}\n\n.agri-reserve-crop-grid.has-more-start {\n  -webkit-mask-image: linear-gradient(to right, transparent, #000 32px);\n  mask-image: linear-gradient(to right, transparent, #000 32px);\n}\n\n.agri-reserve-crop-grid.has-more-start.has-more-end {\n  -webkit-mask-image: linear-gradient(to right, transparent, #000 32px, #000 calc(100% - 32px), transparent);\n  mask-image: linear-gradient(to right, transparent, #000 32px, #000 calc(100% - 32px), transparent);\n}\n\n.agri-reserve-crop-grid.is-refreshing {\n  opacity: 0.45;\n  pointer-events: none;\n}\n\n/* Column = button: header on top, track below. */\n.agri-reserve-crop-col {\n  all: unset;\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  box-sizing: border-box;\n  padding: 2px 4px 0;\n  border-radius: 12px;\n  cursor: pointer;\n  scroll-snap-align: start;\n  transition: opacity 180ms ease, background-color 180ms ease;\n}\n\n/* Hairline divider between columns, inset top and bottom (like VH). */\n.agri-reserve-crop-col:not(:last-child)::after {\n  content: \"\";\n  position: absolute;\n  top: 14px;\n  bottom: 14px;\n  right: 0;\n  width: 1px;\n  background: var(--reserve-divider);\n  pointer-events: none;\n}\n\n.agri-reserve-crop-col:disabled {\n  cursor: default;\n}\n\n.agri-reserve-crop-col:focus-visible {\n  outline: 2px solid var(--reserve-focus);\n  outline-offset: 2px;\n}\n\n/* Selected: a soft wash of its colour, no outline (like VH). */\n.agri-reserve-crop-col.is-selected {\n  background: color-mix(in srgb, var(--bar-color) 10%, transparent);\n}\n\n.agri-reserve-crop-col:not(:disabled):not(.is-selected):hover {\n  background: color-mix(in srgb, var(--bar-color) 6%, transparent);\n}\n\n.agri-reserve-crop-col.is-dimmed {\n  opacity: 0.42;\n}\n\n.agri-reserve-crop-col.is-dimmed:hover {\n  opacity: 0.75;\n}\n\n/* ---- header: value / name / share, aligned across columns ---- */\n\n.agri-reserve-crop-head {\n  display: flex;\n  flex: 0 0 auto;\n  flex-direction: column;\n  align-items: center;\n  gap: 2px;\n  min-width: 0;\n  padding: 4px 2px 0;\n  text-align: center;\n}\n\n.agri-reserve-crop-value {\n  font-size: clamp(12px, 1.4cqi + 6px, 16px);\n  line-height: 1.15;\n  font-weight: 700;\n  letter-spacing: -0.01em;\n  color: var(--reserve-text);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n  animation: agri-reserve-value-in 300ms ease calc(var(--bar-delay) + 260ms) both;\n}\n\n.agri-reserve-crop-value small {\n  font-size: 0.74em;\n  font-weight: 500;\n  color: var(--reserve-text-2);\n}\n\n.agri-reserve-crop-label {\n  max-width: 100%;\n  font-size: clamp(11px, 0.9cqi + 6px, 13.5px);\n  font-weight: 500;\n  line-height: 1.2;\n  color: var(--reserve-text-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.agri-reserve-crop-col.is-selected .agri-reserve-crop-label {\n  color: var(--reserve-text);\n  font-weight: 600;\n}\n\n.agri-reserve-crop-share {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: clamp(10px, 0.6cqi + 6px, 11.5px);\n  font-weight: 500;\n  color: var(--reserve-text-3);\n  font-variant-numeric: tabular-nums;\n}\n\n.agri-reserve-crop-ring {\n  width: 12px;\n  height: 12px;\n  transform: rotate(-90deg);\n}\n\n.agri-reserve-crop-ring circle {\n  fill: none;\n  stroke-width: 3;\n}\n\n.agri-reserve-crop-ring-track {\n  stroke: var(--reserve-ring-track);\n}\n\n.agri-reserve-crop-ring-arc {\n  stroke: var(--bar-color);\n  stroke-linecap: round;\n}\n\n@keyframes agri-reserve-value-in {\n  from {\n    opacity: 0;\n  }\n  to {\n    opacity: 1;\n  }\n}\n\n/* ---- track + bar ---- */\n\n.agri-reserve-crop-plot {\n  display: flex;\n  flex: 1 1 auto;\n  justify-content: center;\n  min-height: 40px;\n  padding: 8px 0 6px;\n  box-sizing: border-box;\n}\n\n/* Full-height faded column of the crop colour behind the bar (like VH):\n   shows the headroom to the largest crop. */\n.agri-reserve-crop-track {\n  position: relative;\n  width: 100%;\n  /* Wide columns (few crops) keep a bar shape instead of a slab. */\n  max-width: 120px;\n  height: 100%;\n  overflow: hidden;\n  border-radius: 14px;\n  background: color-mix(in srgb, var(--bar-color) var(--reserve-track-mix), transparent);\n  transition: background-color 180ms ease;\n}\n\n/* Bright bar in the full crop colour (like VH): flat body, a light sheen on\n   the cap, a glow of its own colour. No darkening toward the base. */\n.agri-reserve-crop-bar {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  height: max(var(--bar-fill), 10px);\n  border-radius: 14px;\n  background: linear-gradient(\n    180deg,\n    color-mix(in srgb, var(--bar-color) 80%, #ffffff) 0%,\n    var(--bar-color) 20%,\n    var(--bar-color) 100%\n  );\n  box-shadow:\n    inset 0 1px 0 rgba(255, 255, 255, 0.45),\n    0 8px 22px -8px color-mix(in srgb, var(--bar-color) 85%, transparent);\n  transform-origin: bottom center;\n  animation: agri-reserve-bar-grow 650ms cubic-bezier(0.22, 1, 0.36, 1) var(--bar-delay) both;\n  transition: filter 160ms ease;\n}\n\n/* Glass highlight on the cap. */\n.agri-reserve-crop-bar::after {\n  content: \"\";\n  position: absolute;\n  top: 4px;\n  left: 24%;\n  right: 24%;\n  height: 3px;\n  border-radius: 2px;\n  background: rgba(255, 255, 255, 0.5);\n}\n\n.agri-reserve-crop-col:not(:disabled):hover .agri-reserve-crop-bar {\n  filter: brightness(1.08);\n}\n\n.agri-reserve-crop-col:not(:disabled):hover .agri-reserve-crop-track {\n  --reserve-track-mix: var(--reserve-track-mix-hover);\n}\n\n/* Selected bar lights up with a wider glow of its own colour. */\n.agri-reserve-crop-col.is-selected .agri-reserve-crop-bar {\n  filter: brightness(1.12) saturate(1.08);\n  box-shadow:\n    inset 0 1px 0 rgba(255, 255, 255, 0.5),\n    0 0 22px -2px color-mix(in srgb, var(--bar-color) 70%, transparent);\n}\n\n.agri-reserve-crop-col.is-selected .agri-reserve-crop-track {\n  overflow: visible;\n}\n\n@keyframes agri-reserve-bar-grow {\n  from {\n    transform: scaleY(0);\n  }\n  to {\n    transform: scaleY(1);\n  }\n}\n\n/* Screen-reader table twin. */\n.agri-reserve-crop-sr {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .agri-reserve-crop-bar,\n  .agri-reserve-crop-value {\n    animation: none;\n  }\n  .agri-reserve-crop-col {\n    transition: none;\n  }\n}\n\n/* ---- card size steps ---- */\n\n/* Narrow card (phone / small tablet column). */\n@container agri-reserve-crop (max-width: 460px) {\n  .agri-reserve-crop-title {\n    margin-bottom: 6px;\n  }\n  .agri-reserve-crop-col {\n    padding: 2px 2px 0;\n  }\n  .agri-reserve-crop-track,\n  .agri-reserve-crop-bar {\n    border-radius: 10px;\n  }\n}\n\n/* Short card: drop the share ring row, tighten the header and the plot. */\n@container agri-reserve-crop (max-height: 230px) {\n  .agri-reserve-crop-title {\n    margin-bottom: 4px;\n  }\n  .agri-reserve-crop-head {\n    gap: 0;\n    padding-top: 2px;\n  }\n  .agri-reserve-crop-share {\n    display: none;\n  }\n  .agri-reserve-crop-plot {\n    min-height: 28px;\n    padding: 4px 0 4px;\n  }\n}\n\n/* Very short card: the bars matter most; the list keeps its aria-label. */\n@container agri-reserve-crop (max-height: 170px) {\n  .agri-reserve-crop-title {\n    display: none;\n  }\n  .agri-reserve-crop-col:not(:last-child)::after {\n    top: 6px;\n    bottom: 6px;\n  }\n}\n\n/* The card padding cannot use its own cqi; step it with the slot instead. */\n@media (max-width: 860px) {\n  .agri-reserve-crop-card {\n    padding: 10px 10px 8px;\n  }\n}\n\n/* ---- states ---- */\n\n.agri-reserve-crop-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  height: 100%;\n  text-align: center;\n  font-size: 13px;\n}\n\n.agri-reserve-crop-empty h3,\n.agri-reserve-crop-empty p {\n  margin: 0;\n  font-size: inherit;\n}\n\n/* Light mode: unit, crop name and share in solid black; names a bit bolder. */\n.agri-reserve-crop-card.light-theme .agri-reserve-crop-value small,\n.agri-reserve-crop-card.light-theme .agri-reserve-crop-share {\n  color: #000000;\n}\n\n.agri-reserve-crop-card.light-theme .agri-reserve-crop-label {\n  color: #000000;\n  font-weight: 600;\n}\n\n.agri-reserve-crop-card.light-theme .agri-reserve-crop-col.is-selected .agri-reserve-crop-label {\n  font-weight: 700;\n}\n"],"sourceRoot":""}]);
